def flow(g, variant):
    h,w=len(g),len(g[0])
    seed=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2][0]
    T = (seed[1]==0 and seed[0]!=0) or (seed[1]==w-1)
    flip = seed[1]==w-1
    gg=[list(r) for r in zip(*g)]
    if flip: gg=[r[:] for r in zip(*g)][::-1]  # placeholder
    # simpler: build transformed grid where flow is downward
    if flip:
        t=[[g[r][w-1-c] for c in range(w)] for r in range(h)]
        gg=[list(r) for r in zip(*t)]  # h? transpose of (h x w) -> w x h
        un=lambda o:[[row[w-1-c] for c in range(len(row))] for row in zip(*o)]
    else:
        gg=[list(r) for r in zip(*g)] if T else [r[:] for r in g]
        un=lambda o:o
    out=[r[:] for r in gg]
    H,W=len(gg),len(gg[0])
    isbar=[[gg[r][c]==8 for c in range(W)] for r in range(H)]
    if variant=='A':
        src={r:set() for r in range(H)}
        for r in range(H):
            for c in range(W):
                if gg[r][c]==2: src[r].add(c)
        for r in range(H):
            s=src[r]
            if not s: continue
            if r+1<H and any(isbar[r+1]):
                marks=set(s)
                for c0 in s:
                    c=c0-1
                    while c>=0:
                        marks.add(c)
                        if gg[r+1][c]==0: break
                        c-=1
                    c=c0+1
                    while c<W:
                        marks.add(c)
                        if gg[r+1][c]==0: break
                        c+=1
                for c in marks: out[r][c]=2
                s=marks
            if r+1<H:
                for c in s:
                    if gg[r+1][c]==0:
                        out[r+1][c]=2; src[r+1].add(c)
    elif variant=='B':  # local: cell spreads only if directly above bar cell
        wet={(r,c) for r in range(H) for c in range(W) if gg[r][c]==2}
        stack=list(wet)
        while stack:
            r,c=stack.pop()
            if r+1>=H: continue
            if gg[r+1][c]==0:
                if (r+1,c) not in wet:
                    wet.add((r+1,c)); out[r+1][c]=2; stack.append((r+1,c))
            elif gg[r+1][c]==8:
                for dc in (-1,1):
                    nc=c+dc
                    if 0<=nc<W and (r,nc) not in wet:
                        wet.add((r,nc)); out[r][nc]=2; stack.append((r,nc))
    elif variant=='C':  # A but source directly above a gap does not spread
        src={r:set() for r in range(H)}
        for r in range(H):
            for c in range(W):
                if gg[r][c]==2: src[r].add(c)
        for r in range(H):
            s=src[r]
            if not s: continue
            if r+1<H and any(isbar[r+1]):
                spread_src={c for c in s if gg[r+1][c]==8}
                marks=set(s)
                for c0 in spread_src:
                    c=c0-1
                    while c>=0:
                        marks.add(c)
                        if gg[r+1][c]==0: break
                        c-=1
                    c=c0+1
                    while c<W:
                        marks.add(c)
                        if gg[r+1][c]==0: break
                        c+=1
                for c in marks: out[r][c]=2
                s=marks
            if r+1<H:
                for c in s:
                    if gg[r+1][c]==0:
                        out[r+1][c]=2; src[r+1].add(c)
    return un(out)

