def core(g, variant):
    # g: flow downward. seed in row 0.
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    src={r:set(c for c in range(W) if g[r][c]==2) for r in range(H)}
    wet=set()
    if variant=='B':
        wet={(0,c) for c in src[0]}
        st=[(r,c) for r in range(H) for c in src[r]] or list(wet)
        st=[(0,c) for c in src[0]]
        while st:
            r,c=st.pop()
            if r+1>=H: continue
            if g[r+1][c]==0:
                if (r+1,c) not in wet:
                    wet.add((r+1,c)); out[r+1][c]=2; st.append((r+1,c))
            elif g[r+1][c]==8:
                for dc in (-1,1):
                    nc=c+dc
                    if 0<=nc<W and (r,nc) not in wet:
                        wet.add((r,nc)); out[r][nc]=2; st.append((r,nc))
        return out
    for r in range(H):
        s=src[r]
        if not s: continue
        if r+1<H and any(g[r+1][c]==8 for c in range(W)):
            if variant=='C':
                sp={c for c in s if g[r+1][c]==8}
            else:
                sp=set(s)
            marks=set(s)
            for c0 in sp:
                c=c0-1
                while c>=0:
                    marks.add(c)
                    if g[r+1][c]==0: break
                    c-=1
                c=c0+1
                while c<W:
                    marks.add(c)
                    if g[r+1][c]==0: break
                    c+=1
            for c in marks: out[r][c]=2
            s=marks
        if r+1<H:
            for c in s:
                if g[r+1][c]==0:
                    out[r+1][c]=2; src[r+1].add(c)
    return out

