def prep(g):
    h,w=len(g),len(g[0])
    seed=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2][0]
    r,c=seed
    if r==0: return g, lambda o:o
    if r==h-1: return g[::-1], lambda o:o[::-1]
    if c==0:
        t=[list(r) for r in zip(*g)]; return t, lambda o:[list(r) for r in zip(*o)]
    t=[list(r) for r in zip(*[[row[w-1-i] for i in range(w)] for row in g])]
    def un(o):
        tp=[list(r) for r in zip(*o)]        # back to h x w
        return [[row[w-1-i] for i in range(w)] for row in tp]
    return t, un

